const { Buffer } = node("buffer");
const hex = (b) => b.toString("hex");
const of = (...bytes) => Buffer.from(bytes);

test("uint8/16/32", () => {
  eq(of(0xff).readUInt8(0), 255);
  eq(of(0x12, 0x34).readUInt16BE(0), 0x1234);
  eq(of(0x12, 0x34).readUInt16LE(0), 0x3412);
  eq(of(0xff, 0xff, 0xff, 0xff).readUInt32BE(0), 4294967295);
  eq(of(1, 2, 3, 4).readUInt32LE(0), 0x04030201);
  eq(of(0, 1, 2, 3, 4).readUInt32BE(1), 0x01020304);
  eq(of(1).readUint8(), 1);
  eq(of(1, 0).readUint16LE(), 1);
  eq(of(0, 0, 0, 1).readUint32BE(), 1);
});
test("int8/16/32", () => {
  eq(of(0xff).readInt8(0), -1);
  eq(of(0x80).readInt8(0), -128);
  eq(of(0x00, 0x80).readInt16LE(0), -32768);
  eq(of(0x80, 0x00).readInt16BE(0), -32768);
  eq(of(0xff, 0xff, 0xff, 0xff).readInt32BE(0), -1);
  eq(of(0x00, 0x00, 0x00, 0x80).readInt32LE(0), -2147483648);
  eq(of(0xff, 0xfe).readInt16BE(0), -2);
});
test("variable width", () => {
  eq(of(1, 2, 3, 4, 5, 6).readUIntBE(0, 6), 0x010203040506);
  eq(of(1, 2, 3, 4, 5, 6).readUIntLE(0, 6), 0x060504030201);
  eq(of(1, 2, 3).readUIntBE(0, 3), 0x010203);
  eq(of(0xff, 0xff, 0xff).readIntBE(0, 3), -1);
  eq(of(0x00, 0x00, 0x80).readIntLE(0, 3), -8388608);
  eq(of(0x80, 0, 0, 0, 0, 0).readIntBE(0, 6), -(2 ** 47));
  code(() => of(1).readUIntBE(0, 7), "ERR_OUT_OF_RANGE", RangeError);
  code(() => of(1).readUIntBE(0, 0), "ERR_OUT_OF_RANGE", RangeError);
  code(() => of(1).readUIntBE(0), "ERR_INVALID_ARG_TYPE", TypeError);
  const w = Buffer.alloc(6);
  w.writeUIntBE(0x010203040506, 0, 6);
  eq(hex(w), "010203040506");
  w.writeUIntLE(0x010203040506, 0, 6);
  eq(hex(w), "060504030201");
  w.writeIntBE(-2, 0, 3);
  eq(hex(w).slice(0, 6), "fffffe");
  w.writeIntLE(-2, 0, 3);
  eq(hex(w).slice(0, 6), "feffff");
});
test("BigInt 64", () => {
  const b = of(1, 2, 3, 4, 5, 6, 7, 8);
  eq(b.readBigUInt64LE(0), 0x0807060504030201n);
  eq(b.readBigUInt64BE(0), 0x0102030405060708n);
  eq(b.readBigUint64LE(), 0x0807060504030201n);
  eq(of(255, 255, 255, 255, 255, 255, 255, 255).readBigInt64LE(0), -1n);
  eq(of(255, 255, 255, 255, 255, 255, 255, 255).readBigUInt64BE(0), 2n ** 64n - 1n);
  eq(of(0x80, 0, 0, 0, 0, 0, 0, 0).readBigInt64BE(0), -(2n ** 63n));
  eq(of(0, 0, 0, 0, 0, 0, 0, 0x80).readBigInt64LE(0), -(2n ** 63n));
  const w = Buffer.alloc(8);
  eq(w.writeBigUInt64LE(0x0807060504030201n, 0), 8);
  eq(hex(w), "0102030405060708");
  w.writeBigUInt64BE(0x0102030405060708n);
  eq(hex(w), "0102030405060708");
  w.writeBigInt64LE(-2n);
  eq(hex(w), "feffffffffffffff");
  w.writeBigInt64BE(-2n);
  eq(hex(w), "fffffffffffffffe");
  code(() => w.writeBigUInt64LE(2n ** 64n), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeBigInt64LE(2n ** 63n), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeBigUInt64LE(-1n), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeBigUInt64LE(1), "ERR_INVALID_ARG_TYPE", TypeError);
});
test("float and double", () => {
  const w = Buffer.alloc(8);
  w.writeDoubleBE(1.5);
  eq(hex(w), "3ff8000000000000");
  w.writeDoubleLE(1.5);
  eq(hex(w), "000000000000f83f");
  eq(w.readDoubleLE(0), 1.5);
  w.writeDoubleBE(-123.456);
  eq(w.readDoubleBE(0), -123.456);
  w.writeDoubleBE(Math.PI);
  eq(hex(w), "400921fb54442d18");
  eq(w.readDoubleBE(), Math.PI);
  w.writeDoubleLE(NaN);
  eq(Number.isNaN(w.readDoubleLE(0)), true);
  w.writeDoubleBE(-Infinity);
  eq(w.readDoubleBE(0), -Infinity);
  w.writeDoubleLE(-0);
  eq(Object.is(w.readDoubleLE(0), -0), true);
  const f = Buffer.alloc(4);
  f.writeFloatBE(1.5);
  eq(hex(f), "3fc00000");
  f.writeFloatLE(1.5);
  eq(hex(f), "0000c03f");
  eq(f.readFloatLE(0), 1.5);
  f.writeFloatBE(0.1);
  eq(f.readFloatBE(0), Math.fround(0.1));
  eq(of(0x7f, 0x80, 0, 0).readFloatBE(0), Infinity);
  eq(w.writeDoubleBE(1, 0), 8);
  eq(f.writeFloatLE(1, 0), 4);
});
test("write ints returns end offset and checks ranges", () => {
  const w = Buffer.alloc(8);
  eq(w.writeUInt8(255, 0), 1);
  eq(w.writeUInt16BE(0x1234, 1), 3);
  eq(w.writeUInt32LE(0x01020304, 3), 7);
  eq(hex(w), "ff123404030201" + "00");
  eq(w.writeInt8(-1, 7), 8);
  eq(w.writeInt16LE(-2, 0), 2);
  eq(w.writeInt32BE(-2, 2), 6);
  eq(hex(w).slice(0, 12), "feff" + "fffffffe");
  eq(w.writeUint16LE(1, 0), 2);
  eq(w.writeUInt8(1), 1);
  const e = code(() => w.writeUInt8(256, 0), "ERR_OUT_OF_RANGE", RangeError);
  eq(e.message, 'The value of "value" is out of range. It must be >= 0 and <= 255. Received 256');
  code(() => w.writeInt8(128, 0), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeInt8(-129, 0), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeUInt16LE(65536, 0), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeUInt32BE(-1, 0), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeInt32LE(2 ** 31, 0), "ERR_OUT_OF_RANGE", RangeError);
  code(() => w.writeUIntBE(2 ** 48, 0, 6), "ERR_OUT_OF_RANGE", RangeError);
});
test("offset validation", () => {
  const b = of(1, 2, 3, 4);
  const e = code(() => b.readUInt8(4), "ERR_OUT_OF_RANGE", RangeError);
  eq(e.message, 'The value of "offset" is out of range. It must be >= 0 and <= 3. Received 4');
  code(() => b.readUInt32LE(1), "ERR_OUT_OF_RANGE", RangeError);
  code(() => b.readUInt8(-1), "ERR_OUT_OF_RANGE", RangeError);
  code(() => b.readUInt8("0"), "ERR_INVALID_ARG_TYPE", TypeError);
  code(() => b.readUInt8(0.5), "ERR_OUT_OF_RANGE", RangeError);
  code(() => b.readUInt8(NaN), "ERR_OUT_OF_RANGE", RangeError);
  const small = of(1);
  const t = code(() => small.readUInt16LE(0), "ERR_BUFFER_OUT_OF_BOUNDS", RangeError);
  eq(t.message, "Attempt to access memory outside buffer bounds");
  code(() => small.readDoubleLE(0), "ERR_BUFFER_OUT_OF_BOUNDS", RangeError);
  code(() => small.writeUInt16LE(1, 0), "ERR_BUFFER_OUT_OF_BOUNDS", RangeError);
  code(() => Buffer.alloc(4).writeDoubleLE(1, 0), "ERR_BUFFER_OUT_OF_BOUNDS", RangeError);
  code(() => Buffer.alloc(8).writeDoubleLE(1, 1), "ERR_OUT_OF_RANGE", RangeError);
});
test("reads respect byteOffset of views", () => {
  const base = Buffer.from([9, 9, 1, 2, 3, 4]);
  const view = base.subarray(2);
  eq(view.readUInt32BE(0), 0x01020304);
  view.writeUInt16BE(0xabcd, 1);
  eq(hex(base), "0909" + "01abcd04");
});
finish();
